const TEMPLATE = "<!DOCTYPE html>
<html lang="pt-BR">
<head>
<meta charset="UTF-8"/>
<meta name="viewport" content="width=device-width, initial-scale=1.0"/>
<title>CRO Next — Gate Humano</title>
<link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap" rel="stylesheet"/>
<script src="https://cdn.jsdelivr.net/npm/marked/marked.min.js"></script>
<style>
:root{--ox:#FF5C28;--ox2:#e84e1b;--dark:#111827;--card:#1f2937;--card2:#273449;--border:#374151;--text:#f9fafb;--muted:#9ca3af;--green:#10b981;--yellow:#f59e0b;--red:#ef4444;--purple:#8b5cf6}
*{box-sizing:border-box;margin:0;padding:0}
body{font-family:'Plus Jakarta Sans',sans-serif;background:var(--dark);color:var(--text);min-height:100vh;display:flex;flex-direction:column}
header{background:rgba(17,24,39,.95);backdrop-filter:blur(12px);border-bottom:1px solid var(--border);padding:0 24px;height:60px;display:flex;align-items:center;justify-content:space-between;position:sticky;top:0;z-index:100}
.hbrand{display:flex;align-items:center;gap:12px}
.logo{width:30px;height:30px;background:linear-gradient(135deg,var(--ox2),var(--ox));border-radius:7px;display:flex;align-items:center;justify-content:center;font-weight:800;font-size:14px;color:#fff}
.btext{font-size:15px;font-weight:700}.btext span{color:var(--ox)}
.gate-badge{background:linear-gradient(135deg,#6d28d9,var(--purple));color:#fff;font-size:10px;font-weight:700;padding:3px 10px;border-radius:20px;letter-spacing:.5px}
main{flex:1;display:flex;gap:0;max-width:1400px;width:100%;margin:0 auto}
aside{width:320px;min-width:280px;border-right:1px solid var(--border);padding:20px 14px;overflow-y:auto}
.aside-t{font-size:11px;font-weight:700;letter-spacing:1px;color:var(--muted);text-transform:uppercase;margin:4px 6px 12px}
.ciclo-card{background:var(--card);border:1px solid var(--border);border-radius:12px;padding:14px;margin-bottom:10px;cursor:pointer;transition:all .15s}
.ciclo-card:hover{border-color:var(--ox)}
.ciclo-card.sel{border-color:var(--ox);box-shadow:0 0 0 1px var(--ox)}
.cc-top{display:flex;justify-content:space-between;align-items:center;margin-bottom:6px}
.cc-cliente{font-weight:700;font-size:14px}
.cc-id{font-size:11px;color:var(--muted);margin-bottom:8px}
.pill{font-size:10px;font-weight:700;padding:2px 8px;border-radius:12px}
.pill.gate{background:rgba(139,92,246,.15);color:var(--purple)}
.pill.rev{background:rgba(245,158,11,.15);color:var(--yellow)}
.score{font-size:11px;font-weight:700}
.score.ok{color:var(--green)}.score.warn{color:var(--yellow)}.score.bad{color:var(--red)}
section{flex:1;padding:24px 28px;overflow-y:auto;min-width:0}
.empty{color:var(--muted);text-align:center;margin-top:80px;font-size:14px}
.empty b{color:var(--text)}
h2.cliente-h{font-size:22px;font-weight:800;margin-bottom:2px}
.sub{color:var(--muted);font-size:12px;margin-bottom:18px}
.kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;margin-bottom:18px}
.kpi{background:var(--card);border:1px solid var(--border);border-radius:12px;padding:12px 14px}
.kpi .l{font-size:10px;font-weight:700;letter-spacing:.6px;color:var(--muted);text-transform:uppercase}
.kpi .v{font-size:19px;font-weight:800;margin-top:3px}
.kpi .d{font-size:11px;font-weight:700;margin-top:2px}
.d.up{color:var(--green)}.d.down{color:var(--red)}.d.flat{color:var(--muted)}
.panel{background:var(--card);border:1px solid var(--border);border-radius:14px;padding:18px;margin-bottom:16px}
.panel h3{font-size:13px;font-weight:800;letter-spacing:.6px;text-transform:uppercase;color:var(--ox);margin-bottom:12px;display:flex;align-items:center;gap:8px}
.panel h3 .n{background:var(--ox);color:#fff;width:20px;height:20px;border-radius:6px;display:inline-flex;align-items:center;justify-content:center;font-size:11px}
.auto-head{display:flex;align-items:center;gap:14px;margin-bottom:8px}
.auto-score{font-size:30px;font-weight:800}
