.alerta-box b{color:var(--red)}
table{width:100%;border-collapse:collapse;font-size:12.5px}
th{text-align:left;color:var(--muted);font-size:10px;text-transform:uppercase;letter-spacing:.6px;padding:6px 8px;border-bottom:1px solid var(--border)}
td{padding:8px;border-bottom:1px solid rgba(55,65,81,.5);vertical-align:top}
.money{color:var(--green);font-weight:700;white-space:nowrap}
