.hip .ht{font-weight:700;font-size:14px;margin-bottom:4px}
.hip .hm{font-size:12px;color:var(--muted);margin-bottom:6px;line-height:1.5}
.hip .tags{display:flex;flex-wrap:wrap;gap:6px}
.tag{font-size:10px;font-weight:700;padding:3px 8px;border-radius:8px;background:rgba(255,92,40,.12);color:var(--ox)}
.tag.g{background:rgba(16,185,129,.12);color:var(--green)}
.tag.b{background:rgba(139,92,246,.12);color:var(--purple)}
.md{font-size:13.5px;line-height:1.65;color:#d1d5db}
.md h1,.md h2{font-size:16px;margin:14px 0 8px;color:var(--text)}
.md h3{font-size:14px;margin:12px 0 6px;color:var(--text)}
.md ul,.md ol{margin:6px 0 10px 20px}.md li{margin-bottom:3px}
.md p{margin-bottom:8px}.md strong{color:var(--text)}
.md table{margin:8px 0}
.gate-actions{background:var(--card);border:1px solid var(--border);border-radius:14px;padding:18px;position:sticky;bottom:12px;box-shadow:0 -8px 30px rgba(0,0,0,.45)}
.ga-row{display:flex;gap:10px;margin-bottom:10px;flex-wrap:wrap}
input[type=text],textarea{background:var(--dark);border:1px solid var(--border);border-radius:10px;color:var(--text);padding:10px 12px;font-family:inherit;font-size:13px;width:100%}
textarea{resize:vertical;min-height:60px}
.btn{border:none;border-radius:10px;padding:12px 22px;font-family:inherit;font-weight:700;font-size:13.5px;cursor:pointer;transition:all .15s}
.btn.apr{background:linear-gradient(135deg,var(--ox2),var(--ox));color:#fff}
.btn.apr:hover{filter:brightness(1.1)}
.btn.rej{background:transparent;border:1px solid var(--border);color:var(--muted)}
.btn.rej:hover{border-color:var(--red);color:var(--red)}
.btn:disabled{opacity:.5;cursor:wait}
.foot-hint{font-size:11px;color:var(--muted);margin-top:8px;line-height:1.5}
.onboard{font-size:11.5px;color:var(--muted);border-top:1px solid var(--border);margin-top:18px;padding:14px 6px;line-height:1.6}
.onboard code{background:var(--card);padding:1px 6px;border-radius:6px;font-size:10.5px}
#toast{position:fixed;bottom:24px;right:24px;background:var(--card);border:1px solid var(--green);color:var(--text);padding:14px 18px;border-radius:12px;font-size:13px;display:none;z-index:999}
@media(max-width:860px){main{flex-direction:column}aside{width:100%;border-right:none;border-bottom:1px solid var(--border)}}
</style>
</head>
<body>
<header>
  <div class="hbrand">
    <div class="logo">C●</div>
    <div class="btext">CRO <span>Next.</span></div>
    <div class="gate-badge">GATE HUMANO</div>
  </div>
  <div style="font-size:11px;color:var(--muted)">Fábrica Multi-Agente · aprovação obrigatória antes de qualquer entrega</div>
</header>
<main>
  <aside>
    <div class="aside-t">Ciclos aguardando decisão</div>
    <div id="lista"></div>
    <div class="onboard">
      <b style="color:var(--text)">Onboarding de cliente novo</b><br/>
