<div id="toast"></div>
<script id="__data" type="application/json">__DATA_PLACEHOLDER__</script>
<script>
var CICLOS = [];
try { CICLOS = JSON.parse(atob(document.getElementById('__data') ? document.getElementById('__data').textContent : '')) || []; } catch(e) { CICLOS = []; }
var sel = null;
function fmtBRL(v){ if(v===null||v===undefined||isNaN(v)) return '—'; return 'R$ ' + Math.round(v).toLocaleString('pt-BR'); }
function fmtN(v){ if(v===null||v===undefined||isNaN(v)) return '—'; return Math.round(v).toLocaleString('pt-BR'); }
function deltaCls(d){ return d>1?'up':(d<-1?'down':'flat'); }
function deltaTxt(d){ if(d===null||d===undefined||isNaN(d)) return ''; return (d>0?'▲ +':(d<0?'▼ ':'')) + d.toFixed(1) + '% vs período anterior'; }
function scoreCls(s){ return s>=7?'ok':(s>=5?'warn':'bad'); }
function esc(s){ var d=document.createElement('div'); d.textContent=(s===null||s===undefined)?'':String(s); return d.innerHTML; }
function parseDados(c){ try { return typeof c.dados_json==='string'?JSON.parse(c.dados_json):(c.dados_json||{}); } catch(e){ return {}; } }
function renderLista(){
  var el = document.getElementById('lista');
  if(!CICLOS.length){ el.innerHTML = '<div style="font-size:12.5px;color:var(--muted);padding:6px">Nenhum ciclo aguardando gate. ✨</div>'; return; }
  el.innerHTML = CICLOS.map(function(c,i){
    var st = c.status==='requer_revisao' ? '<span class="pill rev">REQUER REVISÃO</span>' : '<span class="pill gate">AGUARDA GATE</span>';
    var sc = (c.score_autocritica!==null&&c.score_autocritica!==undefined) ? '<span class="score '+scoreCls(c.score_autocritica)+'">'+Number(c.score_autocritica).toFixed(1)+'/10</span>' : '';
    return '<div class="ciclo-card'+(sel===i?' sel':'')+'" onclick="selecionar('+i+')"><div class="cc-top"><span class="cc-cliente">'+esc(c.cliente)+'</span>'+sc+'</div><div class="cc-id">'+esc(c.ciclo_id)+' · '+esc((c.criado_em||'').slice(0,10))+'</div>'+st+'</div>';
  }).join('');
}
function selecionar(i){ sel = i; renderLista(); renderDetalhe(); window.scrollTo(0,0); }
function renderDetalhe(){
  var c = CICLOS[sel]; if(!c) return;
  var d = parseDados(c);
  var k = d.kpis || {};
  var auto = d.autocritica || {};
  var garg = d.gargalos || [];
  var hips = d.hipoteses || [];
  var anom = d.anomalias || [];
  var html = '';
  html += '<h2 class="cliente-h">'+esc(c.cliente)+'</h2><div class="sub">Ciclo '+esc(c.ciclo_id)+' · gerado em '+esc((c.criado_em||'').slice(0,16).replace('T',' '))+' · período '+esc(d.periodo||'últimos 28 dias')+'</div>';
  html += '<div class="kpis">';
  html += '<div class="kpi"><div class="l">Sessões</div><div class="v">'+fmtN(k.sessoes)+'</div><div class="d '+deltaCls(k.sessoes_delta)+'">'+deltaTxt(k.sessoes_delta)+'</div></div>';
  html += '<div class="kpi"><div class="l">Conversões</div><div class="v">'+fmtN(k.conversoes)+'</div><div class="d '+deltaCls(k.conversoes_delta)+'">'+deltaTxt(k.conversoes_delta)+'</div></div>';
  html += '<div class="kpi"><div class="l">Taxa de conversão</div><div class="v">'+(k.taxa_conversao!==undefined&&k.taxa_conversao!==null?Number(k.taxa_conversao).toFixed(2)+'%':'—')+'</div><div class="d '+deltaCls(k.taxa_delta)+'">'+deltaTxt(k.taxa_delta)+'</div></div>';
  html += '<div class="kpi"><div class="l">Receita (28d)</div><div class="v">'+fmtBRL(k.receita)+'</div><div class="d '+deltaCls(k.receita_delta)+'">'+deltaTxt(k.receita_delta)+'</div></div>';
  html += '<div class="kpi"><div class="l">Oportunidade mapeada</div><div class="v" style="color:var(--green)">'+fmtBRL(d.oportunidade_total_min)+' – '+fmtBRL(d.oportunidade_total_max)+'</div><div class="d flat">por mês, faixa conservadora</div></div>';
  html += '</div>';
  if(anom.length){ html += '<div class="panel"><h3>⚠ Proteção de receita — anomalias detectadas</h3>' + anom.map(function(a){ return '<div class="alerta-box"><b>'+esc(a.severidade||'alerta').toUpperCase()+'</b> · '+esc(a.mensagem||'')+'</div>'; }).join('') + '</div>'; }
  var rec = (auto.recomendacao==='aprovar_para_gate');
  html += '<div class="panel"><h3><span class="n">✓</span> Autocrítica (LLM revisor)</h3><div class="auto-head"><span class="auto-score '+scoreCls(auto.score||0)+'">'+(auto.score!==undefined?Number(auto.score).toFixed(1):'—')+'<span style="font-size:14px;color:var(--muted)">/10</span></span><span class="auto-rec '+(rec?'ok':'warn')+'">'+(rec?'RECOMENDA ENVIO AO GATE':'RECOMENDA REVISÃO')+'</span></div>'
    + (auto.problemas&&auto.problemas.length ? '<ul class="problemas">'+auto.problemas.map(function(p){return '<li>'+esc(p)+'</li>';}).join('')+'</ul>' : '<div style="font-size:12.5px;color:var(--muted)">Nenhum problema relevante apontado pelo revisor.</div>') + '</div>';
  html += '<div class="panel"><h3><span class="n">1</span> Síntese narrativa — material de reunião</h3><div class="md">' + (window.marked?marked.parse(c.sintese_md||d.sintese_md||'_Sem síntese._'):esc(c.sintese_md||'')) + '</div></div>';
  if(garg.length){
    html += '<div class="panel"><h3><span class="n">2</span> Diagnóstico de funil — gargalos em R$</h3><table><thead><tr><th>Etapa</th><th>Evidência</th><th>Uplift estimado</th><th>Oportunidade/mês</th></tr></thead><tbody>';
    garg.forEach(function(g){
      var op = g.oportunidade_reais_mes||{};
      html += '<tr><td><b>'+esc(g.etapa)+'</b><div style="color:var(--muted);font-size:11.5px;margin-top:2px">'+esc(g.descricao||'')+'</div></td><td style="color:var(--muted)">'+esc(g.evidencia||g.evidencias||'')+'</td><td>'+esc(g.uplift_estimado_pct?(g.uplift_estimado_pct.min+'–'+g.uplift_estimado_pct.max+'%'):'—')+'</td><td class="money">'+fmtBRL(op.min)+' – '+fmtBRL(op.max)+'</td></tr>';
    });
    html += '</tbody></table><div class="foot-hint">Premissas e metodologia de cada estimativa estão no JSON do ciclo (auditável). Estimativas sempre em faixa conservadora.</div></div>';
  }
  html += '<div class="panel"><h3><span class="n">3</span> Hipóteses qualificadas — decida a aposta</h3>';
  if(hips.length){
    html += hips.map(function(h,idx){
      var g = h.ganho_estimado_reais||{}; var ice = h.ice||{};
      return '<div class="hip"><input type="checkbox" checked id="hip'+idx+'" data-hid="'+esc(h.id)+'"/><div style="flex:1"><div class="ht">'+esc(h.titulo)+'</div><div class="hm"><b>Problema:</b> '+esc(h.problema_evidenciado||'')+'<br/><b>Solução:</b> '+esc(h.solucao_proposta||'')+'<br/><b>Validação:</b> '+esc(h.criterio_validacao||'')+'</div><div class="tags"><span class="tag">ICE '+(ice.score!==undefined?Number(ice.score).toFixed(1):'—')+'</span><span class="tag g">'+fmtBRL(g.min)+' – '+fmtBRL(g.max)+'/mês</span><span class="tag b">'+esc(h.etapa_funil||'funil')+'</span></div></div></div>';
    }).join('');
    html += '<div class="foot-hint">Hipóteses marcadas serão escritas como cards no Jira do cliente e gravadas na memória de conversão após a aprovação.</div>';
  } else { html += '<div style="font-size:12.5px;color:var(--muted)">Ciclo sem hipóteses (modo sentinela ou erro de pipeline).</div>'; }
  html += '</div>';
  html += '<div class="gate-actions"><div class="ga-row"><input type="text" id="aprovador" placeholder="Seu nome (analista responsável)" style="max-width:280px"/><textarea id="notas" placeholder="Notas do gate: edições, contexto para a entrega, o que descartar…"></textarea></div>'
    + '<div class="ga-row"><button class="btn apr" id="btnApr" onclick="decidir(\'aprovar\')">✓ Aprovar & Entregar (Jira + memória)</button><button class="btn rej" id="btnRej" onclick="decidir(\'rejeitar\')">✕ Rejeitar ciclo</button></div>'
    + '<div class="foot-hint">Nada chega ao cliente sem este gate. A aprovação grava os cards no Jira, alimenta a memória de conversão e notifica o analista.</div></div>';
  document.getElementById('detalhe').innerHTML = html;
}
function decidir(decisao){
  var c = CICLOS[sel]; if(!c) return;
  var aprovador = (document.getElementById('aprovador')||{}).value || '';
  if(decisao==='aprovar' && !aprovador.trim()){ alert('Informe seu nome — o gate registra quem decidiu a aposta.'); return; }
  var notas = (document.getElementById('notas')||{}).value || '';
  var ids = [].slice.call(document.querySelectorAll('.hip input:checked')).map(function(x){ return x.getAttribute('data-hid'); });
  if(decisao==='aprovar' && !ids.length && (parseDados(c).hipoteses||[]).length){ if(!confirm('Nenhuma hipótese selecionada. Aprovar mesmo assim (sem entrega ao Jira)?')) return; }
  document.getElementById('btnApr').disabled = true; document.getElementById('btnRej').disabled = true;
  fetch(window.location.pathname + '/decisao', {
    method:'POST', headers:{'Content-Type':'application/json'},
    body: JSON.stringify({ ciclo_id: c.ciclo_id, decisao: decisao, aprovador: aprovador, notas: notas, hipoteses_ids: ids })
  }).then(function(r){ return r.json().catch(function(){ return {}; }); }).then(function(res){
    var t = document.getElementById('toast');
    t.textContent = decisao==='aprovar' ? '✓ Ciclo aprovado — entregas em processamento (Jira + memória + e-mail).' : 'Ciclo rejeitado e registrado.';
    t.style.display='block';
    setTimeout(function(){ window.location.reload(); }, 2200);
  }).catch(function(e){ alert('Falha ao registrar decisão: '+e); document.getElementById('btnApr').disabled=false; document.getElementById('btnRej').disabled=false; });
}
renderLista();
if(CICLOS.length){ selecionar(0); }
</script>
</body>
</html>
";
const rows = $input.all().map(i => i.json).filter(r => r && (r.status === 'aguardando_gate' || r.status === 'requer_revisao'));
rows.sort((a,b) => String(b.criado_em||'').localeCompare(String(a.criado_em||'')));
const dados = Buffer.from(JSON.stringify(rows), 'utf8').toString('base64');
const html = TEMPLATE.replace('__DATA_PLACEHOLDER__', dados);
return [{ json: { html } }];

const body = ($('POST – Decisão').first().json.body) || {};
const ciclo = $('Ler Ciclo').first().json || {};
let dados = {};
try { dados = typeof ciclo.dados_json === 'string' ? JSON.parse(ciclo.dados_json) : (ciclo.dados_json || {}); } catch (e) {}
const hips = dados.hipoteses || [];
const reg = dados.registro || {};
const ids = body.hipoteses_ids || [];
const sel = hips.filter(h => ids.indexOf(h.id) !== -1);
const aprovar = body.decisao === 'aprovar';
const brl = v => 'R$ ' + Math.round(v || 0).toLocaleString('pt-BR');
const linhas = h => {
  const g = h.ganho_estimado_reais || {}; const ice = h.ice || {};
  return 'h3. ' + (h.titulo || 'Hipótese') + '\n\n'
    + '*Problema evidenciado:* ' + (h.problema_evidenciado || '-') + '\n'
    + '*Solução proposta:* ' + (h.solucao_proposta || '-') + '\n'
    + '*Critério de validação:* ' + (h.criterio_validacao || '-') + '\n'
    + '*Ganho estimado:* ' + brl(g.min) + ' – ' + brl(g.max) + '/mês\n'
    + '*ICE:* ' + (ice.score !== undefined ? ice.score : '-') + ' (I' + (ice.impacto||'-') + '/C' + (ice.confianca||'-') + '/F' + (ice.facilidade||'-') + ')\n'
    + '*Etapa do funil:* ' + (h.etapa_funil || '-') + '\n'
    + '\n_Origem: CRO Next — ciclo ' + ciclo.ciclo_id + ' · aprovado por ' + (body.aprovador||'-') + '_';
};
const entregas = sel.map(h => ({
  hipotese_id: h.id, titulo: h.titulo || 'Hipótese',
  summary: '[CRO] ' + (h.titulo || 'Hipótese qualificada'),
  description: linhas(h), hipotese_json: JSON.stringify(h),
  jira_base_url: String(reg.jira_base_url||'').replace(/\/$/,''), jira_project_key: reg.jira_project_key||'', jira_issue_type: reg.jira_issue_type||'Task',
  cliente: ciclo.cliente, ciclo_id: ciclo.ciclo_id, email_analista: reg.email_analista||'tsoares@cadastra.com'
}));
const cor = aprovar ? '#10b981' : '#ef4444';
const rot = aprovar ? 'APROVADO' : 'REJEITADO';
const email_html = '<div style="font-family:Arial,sans-serif;max-width:640px">' +
  '<h2>🚪 CRO Next — Gate decidido: ' + (ciclo.cliente||'') + '</h2>' +
  '<p><span style="background:'+cor+';color:#fff;padding:3px 10px;border-radius:12px;font-size:12px;font-weight:bold">'+rot+'</span> por <b>'+(body.aprovador||'-')+'</b></p>' +
